/* ГАЛЕРЕЯ ДЕЛОВЫХ ШАБЛОНОВ. Один плагин на два приложения:
   в Таблицах — бюджет отдела, план-график закупок, реестр договоров, платёжный календарь,
   расчёт коммерческого предложения, учёт времени по проектам (формулы, списки, подсветка);
   в Документах — приказ, служебная записка и письмо по ГОСТ Р 7.0.97-2016, доверенность,
   договоры поставки и оказания услуг, коммерческое предложение с вычисляемыми итогами,
   заявление на отпуск. Реквизиты организации запоминаются один раз и подставляются сами;
   незаполненные поля [в скобках] подсвечены. */

const вДокументе = typeof документ !== 'undefined';
const МЕСЯЦЫ_Р = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];
const сегодняТекстом = () => { const д = new Date(); return '«' + String(д.getDate()).padStart(2, '0') + '» ' + МЕСЯЦЫ_Р[д.getMonth()] + ' ' + д.getFullYear() + ' г.'; };
const сегодняЧислами = () => { const д = new Date(); return String(д.getDate()).padStart(2, '0') + '.' + String(д.getMonth() + 1).padStart(2, '0') + '.' + д.getFullYear(); };

/* ===== реквизиты: [метка в шаблоне] ← поле панели ===== */
const РЕКВИЗИТЫ = [['Организация', 'рОрг'], ['Краткое наименование', 'рКратко'], ['ИНН', 'рИНН'], ['КПП', 'рКПП'], ['ОГРН', 'рОГРН'], ['Адрес', 'рАдрес'],
  ['Телефон', 'рТел'], ['E-mail', 'рПочта'], ['Банк', 'рБанк'], ['БИК', 'рБИК'], ['Р/с', 'рРС'], ['К/с', 'рКС'], ['Город', 'рГород'],
  ['Должность руководителя', 'рДолжн'], ['И. О. Фамилия руководителя', 'рПодпись'], ['должности руководителя', 'рДолжнРП'], ['ФИО руководителя', 'рФиоРП']];
function реквизиты(){ return хранилище.взять('реквизиты', {}) || {}; }
function СохранитьРеквизиты(){
  const п = параметры({}), р = {};
  for(const [, к] of РЕКВИЗИТЫ) if(п[к] != null && String(п[к]).trim()) р[к] = String(п[к]).trim();
  хранилище.положить('реквизиты', р);
  панель.сообщение('Реквизиты сохранены в этом браузере: ' + Object.keys(р).length + ' из ' + РЕКВИЗИТЫ.length + '. Они подставятся в шаблоны.');
}
function показатьРеквизиты(){ const р = реквизиты(); for(const [, к] of РЕКВИЗИТЫ) if(р[к]) панель.поле(к, р[к]); }

/* ===== Документы ===== */
const экр = т => String(т).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const П = т => '<p>' + т + '</p>', ПЦ = т => '<p style="text-align:center">' + т + '</p>', ПП = т => '<p style="text-align:right">' + т + '</p>';
const ПО = т => '<p style="text-indent:1.25cm;text-align:justify">' + т + '</p>';
const З = (т, ур = 2) => '<h' + ур + (ур === 1 ? ' style="text-align:center"' : '') + '>' + т + '</h' + ур + '>';
const ДВА = (л, п, ш = 50) => '<table><tr><td style="width:' + ш + '%;border:none;vertical-align:top">' + л + '</td><td style="border:none;vertical-align:top;text-align:right">' + п + '</td></tr></table>';
const ПОДПИСЬ = (кто, фио) => ДВА(кто, '____________ ' + фио, 60);
const РЕКВ_БЛОК = 'ИНН [ИНН], КПП [КПП], ОГРН [ОГРН]<br>Адрес: [Адрес]<br>Р/с [Р/с] в [Банк]<br>К/с [К/с], БИК [БИК]<br>Тел.: [Телефон], e-mail: [E-mail]';
const ДОКУМЕНТЫ = [
  {имя: 'Приказ по основной деятельности', про: 'ГОСТ Р 7.0.97-2016: наименование организации, вид документа, дата и номер, заголовок, «ПРИКАЗЫВАЮ», пункты с исполнителями и сроками, лист ознакомления.', цвет: '#2b6cb0', блоки: [
    '<p style="text-align:center"><b>[Организация]</b></p>', З('ПРИКАЗ', 1), ДВА('[Дата]', '№ [Номер]'), ПЦ('г. [Город]'),
    '<p><b>О [чём приказ]</b></p>',
    ПО('В целях [цель], на основании [основание: закон, решение, служебная записка]'),
    П('ПРИКАЗЫВАЮ:'),
    ПО('1. [Что сделать] — [должность, И. О. Фамилия исполнителя] — в срок до [дата].'),
    ПО('2. [Что сделать] — [должность, И. О. Фамилия исполнителя] — в срок до [дата].'),
    ПО('3. Контроль за исполнением настоящего приказа [возложить на должность, И. О. Фамилия / оставляю за собой].'),
    П('&nbsp;'), ПОДПИСЬ('[Должность руководителя]', '[И. О. Фамилия руководителя]'), П('&nbsp;'),
    П('С приказом ознакомлены:'),
    '<table><tr><th>Должность</th><th>И. О. Фамилия</th><th>Подпись</th><th>Дата</th></tr><tr><td>[должность]</td><td>[И. О. Фамилия]</td><td></td><td></td></tr><tr><td>[должность]</td><td>[И. О. Фамилия]</td><td></td><td></td></tr></table>']},
  {имя: 'Служебная записка', про: 'Внутренний документ: адресат, подразделение, дата и номер, заголовок, текст с предложением и приложения.', цвет: '#3182ce', блоки: [
    ДВА('[Структурное подразделение]', '[Должность адресата]<br>[И. О. Фамилия адресата]'), П('&nbsp;'),
    З('СЛУЖЕБНАЯ ЗАПИСКА', 1), ДВА('[Дата]', '№ [Номер]'),
    '<p><b>О [чём записка]</b></p>',
    ПО('[Изложение обстоятельств: что произошло или что требуется, факты и цифры.]'),
    ПО('В связи с изложенным прошу [предложение или просьба: что, кому и в какой срок сделать].'),
    ПО('Приложение: [наименование] на [N] л. в 1 экз.'),
    П('&nbsp;'), ПОДПИСЬ('[Должность автора]', '[И. О. Фамилия автора]')]},
  {имя: 'Деловое письмо', про: 'Письмо на бланке организации по ГОСТ Р 7.0.97-2016: реквизиты, адресат, заголовок, обращение, подпись и исполнитель.', цвет: '#2c5282', блоки: [
    ДВА('<b>[Организация]</b><br>' + РЕКВ_БЛОК + '<br><br>[Дата] № [Номер]<br>На № [номер] от [дата]', '[Должность адресата]<br>[Организация адресата]<br>[И. О. Фамилия адресата]<br>[Адрес адресата]'),
    П('&nbsp;'), '<p><b>О [чём письмо]</b></p>',
    ПЦ('Уважаемый (-ая) [Имя Отчество]!'),
    ПО('[Текст письма: зачем пишем, суть, просьба или предложение, сроки.]'),
    ПО('[Ожидаемый ответ или следующий шаг.]'),
    ПО('Приложение: [наименование] на [N] л. в 1 экз.'),
    П('С уважением,'), ПОДПИСЬ('[Должность руководителя]', '[И. О. Фамилия руководителя]'), П('&nbsp;'),
    '<p style="font-size:10pt">[Фамилия Имя Отчество исполнителя]<br>[телефон исполнителя]</p>']},
  {имя: 'Доверенность', про: 'Доверенность от организации: на представление интересов, подписание документов или получение ценностей; срок и запрет передоверия.', цвет: '#6b46c1', блоки: [
    З('ДОВЕРЕННОСТЬ № [Номер]', 1), ДВА('г. [Город]', '[Дата прописью]'),
    ПО('[Организация] (ИНН [ИНН], ОГРН [ОГРН], адрес: [Адрес]) в лице [должности руководителя] [ФИО руководителя], действующего на основании [Устава], настоящей доверенностью уполномочивает'),
    ПО('[Фамилия Имя Отчество представителя], [дата рождения] г. р., паспорт серия [серия] № [номер], выдан [кем], [дата выдачи], код подразделения [код], зарегистрированного (-ую) по адресу: [адрес регистрации],'),
    ПО('[представлять интересы организации в … / подписывать от имени организации … / получать от … товарно-материальные ценности по … ]. Для этого представителю предоставляется право [подавать и получать документы, подписывать …, совершать иные действия, связанные с выполнением этого поручения].'),
    ПО('Доверенность выдана сроком до [дата] без права передоверия.'),
    ПО('Подпись представителя [И. О. Фамилия представителя] ____________ удостоверяю.'),
    П('&nbsp;'), ПОДПИСЬ('[Должность руководителя]', '[И. О. Фамилия руководителя]'), П('М. П. (при наличии)')]},
  {имя: 'Договор поставки', про: 'Предмет и спецификация, цена и расчёты, сроки и приёмка, качество, ответственность, форс-мажор, споры, срок действия, реквизиты сторон.', цвет: '#2f855a', блоки: [
    З('ДОГОВОР ПОСТАВКИ № [Номер]', 1), ДВА('г. [Город]', '[Дата]'),
    ПО('[Организация], именуемое в дальнейшем «Поставщик», в лице [должности руководителя] [ФИО руководителя], действующего на основании [Устава], с одной стороны, и [Организация покупателя], именуемое в дальнейшем «Покупатель», в лице [должность, ФИО], действующего на основании [Устава], с другой стороны, вместе именуемые «Стороны», заключили настоящий договор о нижеследующем.'),
    З('1. Предмет договора'),
    ПО('1.1. Поставщик обязуется передавать в собственность Покупателя товар, а Покупатель — принимать и оплачивать его. Наименование, количество, цена и сроки поставки каждой партии согласуются в спецификациях, которые являются неотъемлемой частью договора.'),
    ПО('1.2. Поставщик гарантирует, что товар свободен от прав третьих лиц, не заложен и не находится под арестом.'),
    З('2. Цена и порядок расчётов'),
    ПО('2.1. Цена товара указывается в спецификации в рублях и включает НДС по ставке [22 % / без НДС], стоимость тары, упаковки и маркировки[, а также доставки].'),
    ПО('2.2. Покупатель оплачивает каждую партию [в течение N банковских дней с даты поставки / предоплатой N % в течение N дней с даты счёта]. Обязательство по оплате исполнено с момента зачисления денег на счёт Поставщика.'),
    З('3. Сроки и порядок поставки'),
    ПО('3.1. Товар поставляется [силами Поставщика на склад Покупателя по адресу: … / выборкой со склада Поставщика] в срок, указанный в спецификации.'),
    ПО('3.2. Право собственности и риск случайной гибели товара переходят к Покупателю в момент передачи товара и подписания товарной накладной или универсального передаточного документа.'),
    З('4. Приёмка товара'),
    ПО('4.1. Покупатель принимает товар по количеству и ассортименту при получении, по качеству — в течение [N] рабочих дней. О несоответствии Покупатель письменно уведомляет Поставщика с приложением акта.'),
    ПО('4.2. Поставщик за свой счёт допоставляет недостающий или заменяет некачественный товар в течение [N] рабочих дней с получения уведомления.'),
    З('5. Качество и гарантия'),
    ПО('5.1. Качество товара должно соответствовать обязательным требованиям, сертификатам или декларациям соответствия и условиям спецификации. Гарантийный срок — [N месяцев / срок изготовителя].'),
    З('6. Ответственность сторон'),
    ПО('6.1. За просрочку поставки Поставщик уплачивает неустойку [0,1] % от стоимости непоставленного в срок товара за каждый день просрочки, но не более [10] % его стоимости.'),
    ПО('6.2. За просрочку оплаты Покупатель уплачивает неустойку [0,1] % от неоплаченной суммы за каждый день просрочки, но не более [10] % этой суммы.'),
    З('7. Обстоятельства непреодолимой силы'),
    ПО('7.1. Стороны освобождаются от ответственности за неисполнение обязательств, вызванное обстоятельствами непреодолимой силы, если письменно уведомили о них другую сторону в течение [5] рабочих дней с их наступления.'),
    З('8. Разрешение споров'),
    ПО('8.1. Споры решаются переговорами; претензионный порядок обязателен, срок ответа на претензию — [10] рабочих дней. Неурегулированный спор передаётся в Арбитражный суд [субъекта РФ].'),
    З('9. Срок действия и прочие условия'),
    ПО('9.1. Договор вступает в силу с момента подписания и действует до [дата], а в части расчётов — до полного их завершения.'),
    ПО('9.2. Изменения и дополнения действительны, если составлены письменно и подписаны обеими сторонами. Документы, подписанные электронной подписью или переданные по электронной почте с последующим обменом оригиналами, имеют силу до получения оригиналов.'),
    З('10. Реквизиты и подписи сторон'),
    ДВА('<b>Поставщик</b><br>[Организация]<br>' + РЕКВ_БЛОК + '<br><br>[Должность руководителя]<br>____________ [И. О. Фамилия руководителя]',
      '<div style="text-align:left"><b>Покупатель</b><br>[Организация покупателя]<br>ИНН [ИНН], КПП [КПП]<br>Адрес: [адрес]<br>Р/с [р/с] в [банк]<br>К/с [к/с], БИК [БИК]<br><br>[Должность]<br>____________ [И. О. Фамилия]</div>')]},
  {имя: 'Договор оказания услуг', про: 'Предмет и сроки, стоимость и оплата, сдача-приёмка по акту, права и обязанности, ответственность, конфиденциальность, реквизиты сторон.', цвет: '#38a169', блоки: [
    З('ДОГОВОР ВОЗМЕЗДНОГО ОКАЗАНИЯ УСЛУГ № [Номер]', 1), ДВА('г. [Город]', '[Дата]'),
    ПО('[Организация заказчика], именуемое в дальнейшем «Заказчик», в лице [должность, ФИО], действующего на основании [Устава], с одной стороны, и [Организация], именуемое в дальнейшем «Исполнитель», в лице [должности руководителя] [ФИО руководителя], действующего на основании [Устава], с другой стороны, заключили настоящий договор о нижеследующем.'),
    З('1. Предмет договора'),
    ПО('1.1. Исполнитель обязуется по заданию Заказчика оказать услуги [описание услуг] (далее — услуги), а Заказчик обязуется оплатить их. Состав, объём и требования к услугам приведены в задании (приложение № 1).'),
    ПО('1.2. Срок оказания услуг: с [дата] по [дата].'),
    З('2. Стоимость и порядок оплаты'),
    ПО('2.1. Стоимость услуг составляет [сумма] ([сумма прописью]) руб., [в том числе НДС 22 % — сумма / НДС не облагается в связи с …].'),
    ПО('2.2. Заказчик оплачивает услуги [в течение N банковских дней с даты подписания акта / авансом N %, остаток — после подписания акта].'),
    З('3. Сдача и приёмка услуг'),
    ПО('3.1. По окончании оказания услуг (этапа) Исполнитель передаёт Заказчику акт сдачи-приёмки. Заказчик в течение [5] рабочих дней подписывает акт или направляет мотивированный отказ.'),
    ПО('3.2. Если в этот срок Заказчик не подписал акт и не направил отказ, услуги считаются принятыми.'),
    З('4. Права и обязанности сторон'),
    ПО('4.1. Исполнитель оказывает услуги лично [или с привлечением третьих лиц, отвечая за их действия], качественно и в срок, информирует Заказчика о ходе оказания услуг по его запросу.'),
    ПО('4.2. Заказчик предоставляет Исполнителю сведения и документы, необходимые для оказания услуг, в течение [3] рабочих дней с запроса.'),
    З('5. Ответственность и конфиденциальность'),
    ПО('5.1. За нарушение сроков оказания услуг Исполнитель уплачивает пеню [0,1] % от стоимости услуг за каждый день просрочки; за нарушение сроков оплаты Заказчик уплачивает пеню [0,1] % от неоплаченной суммы за каждый день просрочки.'),
    ПО('5.2. Стороны не раскрывают третьим лицам сведения, полученные в ходе исполнения договора, кроме случаев, предусмотренных законом.'),
    З('6. Прочие условия'),
    ПО('6.1. Договор вступает в силу с момента подписания и действует до полного исполнения обязательств. Заказчик вправе отказаться от договора, оплатив фактически понесённые Исполнителем расходы (ст. 782 ГК РФ).'),
    ПО('6.2. Споры, не урегулированные в претензионном порядке (срок ответа — [10] рабочих дней), рассматриваются в Арбитражном суде [субъекта РФ].'),
    З('7. Реквизиты и подписи сторон'),
    ДВА('<b>Исполнитель</b><br>[Организация]<br>' + РЕКВ_БЛОК + '<br><br>[Должность руководителя]<br>____________ [И. О. Фамилия руководителя]',
      '<div style="text-align:left"><b>Заказчик</b><br>[Организация заказчика]<br>ИНН [ИНН], КПП [КПП]<br>Адрес: [адрес]<br>Р/с [р/с] в [банк]<br>К/с [к/с], БИК [БИК]<br><br>[Должность]<br>____________ [И. О. Фамилия]</div>')]},
  {имя: 'Коммерческое предложение', про: 'Предложение клиенту: таблица позиций, итог и НДС 22 % считаются сами при правке цен и количества; условия и срок действия.', цвет: '#dd6b20', блоки: [
    ДВА('<b>[Организация]</b><br>[Адрес]<br>Тел.: [Телефон], [E-mail]', '[Должность адресата]<br>[Организация адресата]<br>[И. О. Фамилия адресата]'),
