function Выбран(){
  const п = параметры({}), ш = галерея().find(x => x.имя === п.шаблон);
  if(ш) панель.поле('описание', [{текст: ш.имя + '\n', жирный: true}, {текст: ш.про, цвет: '#3b4252'}]);
}
async function Вставить(){
  const п = параметры({}), ш = галерея().find(x => x.имя === п.шаблон);
  if(!ш){ панель.сообщение('Выберите шаблон в галерее.'); return; }
  if(вДокументе){ await вставитьДокумент(ш); return; }
  const ок = await разложитьШаблон(ш);
  if(ок) панель.сообщение('Готово: «' + ш.имя + '». Жёлтые клетки — для ввода; [в скобках] — заменить своим.');
}
